   "text": "某畫廊內有 $33$ 幅油畫。下面的框線圖顯示該畫廊內的油畫的價錢（以千元為單位）的分佈。已知這分佈的平均值為 $53$ 千元。\n\n![2014 P1 Q11 框線圖](2014P1_figs_svg/2014P1_Q11.svg)\n\n(a)　求上述分佈的分佈域及四分位數間距。（3 分）\n\n(b)　現將價錢（以千元為單位）分別為 $32$、$34$、$58$ 及 $59$ 的四幅油畫捐贈給一博物館。求該畫廊內餘下的油畫的價錢的平均值及中位數。（3 分）",
   "html": "<p>11.&nbsp;&nbsp;&nbsp;某畫廊內有 $33$ 幅油畫。下面的框線圖顯示該畫廊內的油畫的價錢（以千元為單位）的分佈。已知這分佈的平均值為 $53$ 千元。</p>\n<p><img alt=\"2014 P1 Q11 框線圖\" src=\"2014P1_figs_svg/2014P1_Q11.svg\" /></p>\n<p>(a)　求上述分佈的分佈域及四分位數間距。（3 分）</p>\n<p>(b)　現將價錢（以千元為單位）分別為 $32$、$34$、$58$ 及 $59$ 的四幅油畫捐贈給一博物館。求該畫廊內餘下的油畫的價錢的平均值及中位數。（3 分）</p>",
