   "text": "$A$ 委員會的委員年歲如下：\n\n| | | | | | | | | | |\n|---|---|---|---|---|---|---|---|---|---|\n| 17 | 18 | 21 | 21 | 22 | 22 | 23 | 23 | 23 | 31 |\n| 31 | 34 | 35 | 36 | 47 | 47 | 58 | 68 | 69 | 69 |\n\n(a) 寫出 $A$ 委員會的委員年歲的中位數及眾數。（2 分）\n\n(b) 下面的幹葉圖顯示 $B$ 委員會的委員年歲的分佈。已知這分佈的分佈域為 47。\n\n![2013 P1 Q10 幹葉圖](2013P1_figs_svg/2013P1_Q10.svg)\n\n　(i) 求 $a$ 及 $b$。\n\n　(ii) 現從每個委員會中，各隨機選出一名委員作該委員會的代表。當該兩名代表的年歲之差超過 40 時，他們便可參加某比賽。求這兩名代表可參加該比賽的概率。（4 分）",
   "html": "<p>10.&nbsp;&nbsp;&nbsp;$A$ 委員會的委員年歲如下：</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>17</td>\n<td>18</td>\n<td>21</td>\n<td>21</td>\n<td>22</td>\n<td>22</td>\n<td>23</td>\n<td>23</td>\n<td>23</td>\n<td>31</td>\n</tr>\n<tr>\n<td>31</td>\n<td>34</td>\n<td>35</td>\n<td>36</td>\n<td>47</td>\n<td>47</td>\n<td>58</td>\n<td>68</td>\n<td>69</td>\n<td>69</td>\n</tr>\n</tbody>\n</table>\n<p>(a) 寫出 $A$ 委員會的委員年歲的中位數及眾數。（2 分）</p>\n<p>(b) 下面的幹葉圖顯示 $B$ 委員會的委員年歲的分佈。已知這分佈的分佈域為 47。</p>\n<p><img alt=\"2013 P1 Q10 幹葉圖\" src=\"2013P1_figs_svg/2013P1_Q10.svg\" /></p>\n<p>(i) 求 $a$ 及 $b$。</p>\n<p>(ii) 現從每個委員會中，各隨機選出一名委員作該委員會的代表。當該兩名代表的年歲之差超過 40 時，他們便可參加某比賽。求這兩名代表可參加該比賽的概率。（4 分）</p>",
