   "text": "一周界為 $\\ell$ 米的托盤的重量為 $W$ 克。已知 $W$ 為兩部分之和，一部分隨 $\\ell$ 正變，另一部分隨 $\\ell^2$ 正變。當 $\\ell=1$ 時，$W=181$；且當 $\\ell=2$ 時，$W=402$。\n\n(a) 求一周界為 1.2 米的托盤的重量。（4 分）\n\n(b) 若一托盤的重量為 594 克，求該托盤的周界。（2 分）",
   "html": "<p>11.&nbsp;&nbsp;&nbsp;一周界為 $\\ell$ 米的托盤的重量為 $W$ 克。已知 $W$ 為兩部分之和，一部分隨 $\\ell$ 正變，另一部分隨 $\\ell^2$ 正變。當 $\\ell=1$ 時，$W=181$；且當 $\\ell=2$ 時，$W=402$。</p>\n<p>(a) 求一周界為 1.2 米的托盤的重量。（4 分）</p>\n<p>(b) 若一托盤的重量為 594 克，求該托盤的周界。（2 分）</p>",
