   "text": "下面的框線圖顯示某班學生在一測驗中得分（以分為單位）的分佈。在該測驗中，素珊獲最高得分，而志諺獲得 65 分。素珊及志諺在該測驗中的標準分分別為 3 及 0.5。\n\n![2013 P1 Q15 框線圖](2013P1_figs_svg/2013P1_Q15.svg)\n\n(a) 求該分佈的平均值。（2 分）\n\n(b) 素珊宣稱在該測驗中至少一半學生的標準分均為負值。你是否同意？試解釋你的答案。（2 分）",
