   "html": "<p>6.&nbsp;&nbsp;&nbsp;(a)　求同時滿足</p>\n<p>$$\\frac{4x+6}{7} &gt; 2(x-3) \\quad\\text{及}\\quad 2x-10 \\le 0$$</p>\n<p>的 $x$ 值的範圍。</p>\n<p>(b)　有多少個正整數同時滿足 (a) 的不等式？（4 分）</p>",
