   "text": "圖 2 中，實心直立角柱體 $ABCDEFGH$ 的體積為 1020 cm³。該角柱體的底 $ABCD$ 為一梯形，其中 $AD$ 平行於 $BC$。已知 $\\angle BAD = 90^\\circ$、$AB=12$ cm、$BC=6$ cm 及 $DE=10$ cm。\n\n![Q9 圖 2](2012_P1_figs_svg/2012P1_Q9.svg)\n\n求\n\n(a)　$AD$ 的長度，\n\n(b)　角柱體 $ABCDEFGH$ 的總表面積。（5 分）",
   "html": "<p>9.&nbsp;&nbsp;&nbsp;圖 2 中，實心直立角柱體 $ABCDEFGH$ 的體積為 1020 cm³。該角柱體的底 $ABCD$ 為一梯形，其中 $AD$ 平行於 $BC$。已知 $\\angle BAD = 90^\\circ$、$AB=12$ cm、$BC=6$ cm 及 $DE=10$ cm。</p>\n<p><img alt=\"Q9 圖 2\" src=\"2012_P1_figs_svg/2012P1_Q9.svg\" /></p>\n<p>求</p>\n<p>(a)　$AD$ 的長度，</p>\n<p>(b)　角柱體 $ABCDEFGH$ 的總表面積。（5 分）</p>",
