   "text": "圓 $C$ 的圓心的坐標為 $(6,10)$。已知 $x$ 軸為 $C$ 的切線。\n\n(a)　求 $C$ 的方程。（2 分）\n\n(b)　直線 $L$ 的斜率及 $y$ 截距分別為 $-1$ 及 $k$。若 $L$ 與 $C$ 相交於 $A$ 及 $B$，以 $k$ 表 $AB$ 的中點的坐標。（5 分）",
   "html": "<p>17.&nbsp;&nbsp;&nbsp;圓 $C$ 的圓心的坐標為 $(6,10)$。已知 $x$ 軸為 $C$ 的切線。</p>\n<p>(a)　求 $C$ 的方程。（2 分）</p>\n<p>(b)　直線 $L$ 的斜率及 $y$ 截距分別為 $-1$ 及 $k$。若 $L$ 與 $C$ 相交於 $A$ 及 $B$，以 $k$ 表 $AB$ 的中點的坐標。（5 分）</p>",
