   "text": "在某城市，一機場的空運貨站 $X$ 自它開始運作起計的第 $n$ 年所處理的貨物的重量為 $A(n)$ 公噸，其中 $n$ 為一正整數。已知 $A(n)=ab^{2n}$，其中 $a$ 及 $b$ 均為正常數。現知 $X$ 自它開始運作起計的第 1 年及第 2 年所處理的貨物的重量分別為 254100 公噸及 307461 公噸。\n\n(a)\n\n　　(i)　求 $a$ 及 $b$。由此求 $X$ 自它開始運作起計的第 4 年所處理的貨物的重量。\n\n　　(ii)　以 $n$ 表 $X$ 自它開始運作起計的首 $n$ 年所處理的貨物的總重量。（6 分）\n\n(b)　自 $X$ 運作了 4 年，空運貨站 $Y$ 開始運作。設 B$(m)$ 公噸為 $Y$ 自它開始運作起計的第 $m$ 年所處理的貨物的重量，其中 $m$ 為一正整數。已知 B$(m) = 2ab^m$。\n\n　　(i)　該機場的經理宣稱 $Y$ 運作後，每一年 $Y$ 所處理的貨物的重量均較 $X$ 所處理的少。你是否同意？試解釋你的答案。\n\n　　(ii)　該機場的監督認為當 $X$ 和 $Y$ 所處理的貨物自 $X$ 開始運作起計的總重量超出 20 000 000 公噸時，應安裝新設施以維持空運貨站的工作效能。根據該監督的想法，自 $X$ 開始運作起計的哪一年應安裝新設施？（7 分）",
   "html": "<p>19.&nbsp;&nbsp;&nbsp;在某城市，一機場的空運貨站 $X$ 自它開始運作起計的第 $n$ 年所處理的貨物的重量為 $A(n)$ 公噸，其中 $n$ 為一正整數。已知 $A(n)=ab^{2n}$，其中 $a$ 及 $b$ 均為正常數。現知 $X$ 自它開始運作起計的第 1 年及第 2 年所處理的貨物的重量分別為 254100 公噸及 307461 公噸。</p>\n<p>(a)</p>\n<p>(i)　求 $a$ 及 $b$。由此求 $X$ 自它開始運作起計的第 4 年所處理的貨物的重量。</p>\n<p>(ii)　以 $n$ 表 $X$ 自它開始運作起計的首 $n$ 年所處理的貨物的總重量。（6 分）</p>\n<p>(b)　自 $X$ 運作了 4 年，空運貨站 $Y$ 開始運作。設 B$(m)$ 公噸為 $Y$ 自它開始運作起計的第 $m$ 年所處理的貨物的重量，其中 $m$ 為一正整數。已知 B$(m) = 2ab^m$。</p>\n<p>(i)　該機場的經理宣稱 $Y$ 運作後，每一年 $Y$ 所處理的貨物的重量均較 $X$ 所處理的少。你是否同意？試解釋你的答案。</p>\n<p>(ii)　該機場的監督認為當 $X$ 和 $Y$ 所處理的貨物自 $X$ 開始運作起計的總重量超出 20 000 000 公噸時，應安裝新設施以維持空運貨站的工作效能。根據該監督的想法，自 $X$ 開始運作起計的哪一年應安裝新設施？（7 分）</p>",
