   "text": "If $ k $ is a constant such that $ x^3 + 4x^2 + kx - 12 $ is divisible by $ x + 3 $, then $ k = $\n\n- A. $-25$.\n- B. $-1$.\n- C. $1$.\n- D. $17$.",
