   "html": "<p>5.&nbsp;&nbsp;&nbsp;If $ m + 2n + 6 = 2m - n = 7 $, then $ n = $</p>\n<ul><li>A. $-4$.</li><li>B. $-1$.</li><li>C. $3$.</li><li>D. $11$.</li></ul>",
