   "html": "<p>10.&nbsp;&nbsp;&nbsp;It is given that $y$ partly varies directly as $x^2$ and partly varies inversely as $x$. When $x=1$, $y=-4$ and when $x=2$, $y=5$. When $x=-2$, $y=$</p>\n<ul><li>A. -11.</li><li>B. -5.</li><li>C. 5.</li><li>D. 11.</li></ul>",
