   "html": "<p>33.&nbsp;&nbsp;&nbsp;AD0000002012$_{16}$ =</p>\n<ul><li>A. $ (10)16^{11} + (13)16^{10} + 8210 $</li><li>B. $ (10)16^{12} + (13)16^{11} + 131360 $</li><li>C. $ (11)16^{11} + (14)16^{10} + 8210 $</li><li>D. $ (11)16^{12} + (14)16^{11} + 131360 $</li></ul>",
